scripts.天王岛游客对话.txt:
	If ($SubEvent18 == 0) @Sub18;

	Goto @Talk;
@Sub18:
	SetObjScript("支线宝箱", "支线18宝箱.txt");
	SaveObj();
	Assign($SubEvent18, 10);
	Goto @Talk;
	Return;

@Talk:
	Say("天王岛游客：公子，可听说过洞庭湖的天王岛？");
	Say("杨影枫：很小时听家父提起过。", 2);
	Say("天王岛游客：我就是从那天王岛来的。");
	Say("杨影枫：哦？那天王岛是何地呀？", 2);
	Say("天王岛游客：想当年那天王岛可是武林盟主孤独剑夫妇的宅邸，也曾风光一时呀！");
	Say("杨影枫：哦，那你是？", 2);
	Say("天王岛游客：我只是天王岛管家的孙子，我听爷爷说孤独大侠的“孤独剑”流落江湖，特来找寻。");
	Say("杨影枫：那可又音讯？", 2);
	Say("天王岛游客：听说有人在此地见过，可我没有寻到，也许它是在等它真正的主人吧！");
	Say("杨影枫：也是，要有缘之人方能得之。", 2);
	Return;

